package com.example.smarttasks.data

import androidx.room.TypeConverter
import com.example.smarttasks.model.PrioridadTarea

class Converters {

    @TypeConverter
    fun fromPrioridad(prioridad: PrioridadTarea): String {
        return prioridad.name
    }

    @TypeConverter
    fun toPrioridad(prioridad: String): PrioridadTarea {
        return PrioridadTarea.valueOf(prioridad)
    }
}

package com.example.smarttasks.data

import androidx.room.Database
import androidx.room.Room
import androidx.room.RoomDatabase
import androidx.room.TypeConverters
import android.content.Context
import com.example.smarttasks.model.Tarea

@Database(
    entities = [Tarea::class],
    version = 1,
    exportSchema = false
)
@TypeConverters(Converters::class)
abstract class SmartTasksDatabase : RoomDatabase() {

    abstract fun tareaDao(): TareaDao

    companion object {
        @Volatile
        private var INSTANCE: SmartTasksDatabase? = null

        fun getDatabase(context: Context): SmartTasksDatabase {
            return INSTANCE ?: synchronized(this) {
                val instance = Room.databaseBuilder(
                    context.applicationContext,
                    SmartTasksDatabase::class.java,
                    "smarttasks_database"
                ).build()
                INSTANCE = instance
                instance
            }
        }
    }
}

package com.example.smarttasks.data

import androidx.room.*
import com.example.smarttasks.model.Tarea
import kotlinx.coroutines.flow.Flow

@Dao
interface TareaDao {

    @Query("SELECT * FROM tareas ORDER BY fechaCreacion DESC")
    fun getAllTareas(): Flow<List<Tarea>>

    @Query("SELECT * FROM tareas WHERE completada = 0 ORDER BY fechaCreacion DESC")
    fun getTareasPendientes(): Flow<List<Tarea>>

    @Query("SELECT * FROM tareas WHERE completada = 1 ORDER BY fechaCompletada DESC")
    fun getTareasCompletadas(): Flow<List<Tarea>>

    @Query("SELECT * FROM tareas WHERE id = :id")
    suspend fun getTareaById(id: Int): Tarea?

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insertTarea(tarea: Tarea)

    @Update
    suspend fun updateTarea(tarea: Tarea)

    @Delete
    suspend fun deleteTarea(tarea: Tarea)

    @Query("UPDATE tareas SET completada = :completada, fechaCompletada = :fecha WHERE id = :id")
    suspend fun marcarComoCompletada(id: Int, completada: Boolean, fecha: Long?)

    @Query("DELETE FROM tareas WHERE completada = 1")
    suspend fun deleteAllCompletadas()
}

package com.example.smarttasks.model
import androidx.room.Entity import androidx.room.PrimaryKey import java.util.Date
@Entity(tableName = "tareas") data class Tarea( @PrimaryKey(autoGenerate = true) val id: Int = 0, val titulo: String, val descripcion: String = "", val completada: Boolean = false, val fechaCreacion: Long = System.currentTimeMillis(), val fechaCompletada: Long? = null, val prioridad: PrioridadTarea = PrioridadTarea.MEDIA )
enum class PrioridadTarea { ALTA, MEDIA, BAJA }

package com.example.smarttasks.navigation

import androidx.compose.runtime.Composable
import androidx.navigation.NavHostController
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import com.example.smarttasks.ui.screens.MainScreen
import com.example.smarttasks.ui.screens.AddTaskScreen

@Composable
fun SmartTasksNavGraph(
    navController: NavHostController
) {
    NavHost(
        navController = navController,
        startDestination = SmartTasksDestinations.MAIN
    ) {
        composable(SmartTasksDestinations.MAIN) {
            MainScreen(
                onNavigateToAddTask = {
                    navController.navigate(SmartTasksDestinations.ADD_TASK)
                }
            )
        }

        composable(SmartTasksDestinations.ADD_TASK) {
            AddTaskScreen(
                navController = navController
            )
        }
    }
}

// Constantes para las rutas (mejores prácticas)
object SmartTasksDestinations {
    const val MAIN = "main"
    const val ADD_TASK = "add_task"
}

