// Paleta Futurista y Tranquila - Modo Claro val CyberBlue = Color(0xFF00D4FF) // Azul cibernético vibrante val SoftTeal = Color(0xFF4ECDC4) // Verde azulado suave val LightCyan = Color(0xFF89E5DC) // Cian claro relajante val DeepSpace = Color(0xFF1B2951) // Azul espacial profundo val CloudWhite = Color(0xFFF8FFFE) // Blanco nube val SilverMist = Color(0xFFE8F4F8) // Plata nebulosa
// Paleta Futurista y Tranquila - Modo Oscuro val NeonCyan = Color(0xFF00FFF0) // Cian neón val ElectricBlue = Color(0xFF0099CC) // Azul eléctrico val DeepTeal = Color(0xFF006B7D) // Verde azulado profundo val SpaceGray = Color(0xFF1A1D29) // Gris espacial val DarkVoid = Color(0xFF0B0E1A) // Vacío oscuro val GlowWhite = Color(0xFFE0F8FF) // Blanco luminoso
// Colores de acento y estado val SuccessGreen = Color(0xFF00E676) // Verde éxito futurista val WarningAmber = Color(0xFFFFB74D) // Ámbar advertencia val ErrorRed = Color(0xFFFF5252) // Rojo error suave val InfoBlue = Color(0xFF40C4FF) // Azul información

package com.example.smarttasks.ui.theme

import android.app.Activity
import android.os.Build
import androidx.compose.foundation.isSystemInDarkTheme
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.darkColorScheme
import androidx.compose.material3.dynamicDarkColorScheme
import androidx.compose.material3.dynamicLightColorScheme
import androidx.compose.material3.lightColorScheme
import androidx.compose.runtime.Composable
import androidx.compose.ui.platform.LocalContext

private val DarkColorScheme = darkColorScheme(
    primary = Purple80,
    secondary = PurpleGrey80,
    tertiary = Pink80
)

private val LightColorScheme = lightColorScheme(
    primary = Purple40,
    secondary = PurpleGrey40,
    tertiary = Pink40

    /* Other default colors to override
    background = Color(0xFFFFFBFE),
    surface = Color(0xFFFFFBFE),
    onPrimary = Color.White,
    onSecondary = Color.White,
    onTertiary = Color.White,
    onBackground = Color(0xFF1C1B1F),
    onSurface = Color(0xFF1C1B1F),
    */
)

@Composable
fun SmartTasksTheme(
    darkTheme: Boolean = isSystemInDarkTheme(),
    // Dynamic color is available on Android 12+
    dynamicColor: Boolean = true,
    content: @Composable () -> Unit
) {
    val colorScheme = when {
        dynamicColor && Build.VERSION.SDK_INT >= Build.VERSION_CODES.S -> {
            val context = LocalContext.current
            if (darkTheme) dynamicDarkColorScheme(context) else dynamicLightColorScheme(context)
        }

        darkTheme -> DarkColorScheme
        else -> LightColorScheme
    }

    MaterialTheme(
        colorScheme = colorScheme,
        typography = Typography,
        content = content
    )
}

package com.example.smarttasks.ui.theme
import android.os.Build import androidx.compose.foundation.isSystemInDarkTheme import androidx.compose.material3.MaterialTheme import androidx.compose.material3.darkColorScheme import androidx.compose.material3.dynamicDarkColorScheme import androidx.compose.material3.dynamicLightColorScheme import androidx.compose.material3.lightColorScheme import androidx.compose.runtime.Composable import androidx.compose.ui.platform.LocalContext
// Esquema de colores para modo oscuro - Futurista y tranquilo private val DarkColorScheme = darkColorScheme( primary = NeonCyan, onPrimary = DarkVoid, primaryContainer = DeepTeal, onPrimaryContainer = GlowWhite,
secondary = ElectricBlue, onSecondary = DarkVoid, secondaryContainer = SpaceGray, onSecondaryContainer = GlowWhite,
tertiary = InfoBlue, onTertiary = DarkVoid, tertiaryContainer = DeepSpace, onTertiaryContainer = GlowWhite,
background = DarkVoid, onBackground = GlowWhite, surface = SpaceGray, onSurface = GlowWhite, surfaceVariant = DeepSpace, onSurfaceVariant = LightCyan,
outline = DeepTeal, outlineVariant = ElectricBlue,
error = ErrorRed, onError = DarkVoid, errorContainer = DeepSpace, onErrorContainer = GlowWhite )
// Esquema de colores para modo claro - Futurista y tranquilo private val LightColorScheme = lightColorScheme( primary = CyberBlue, onPrimary = CloudWhite, primaryContainer = LightCyan, onPrimaryContainer = DeepSpace,
secondary = SoftTeal, onSecondary = CloudWhite, secondaryContainer = SilverMist, onSecondaryContainer = DeepSpace,
tertiary = InfoBlue, onTertiary = CloudWhite, tertiaryContainer = LightCyan, onTertiaryContainer = DeepSpace,
background = CloudWhite, onBackground = DeepSpace, surface = SilverMist, onSurface = DeepSpace, surfaceVariant = LightCyan, onSurfaceVariant = DeepTeal,
outline = SoftTeal, outlineVariant = CyberBlue,
error = ErrorRed, onError = CloudWhite, errorContainer = SilverMist, onErrorContainer = DeepSpace )
@Composable fun SmartTasksTheme( darkTheme: Boolean = isSystemInDarkTheme(), // Dynamic color deshabilitado para mantener nuestra paleta futurista dynamicColor: Boolean = false, content: @Composable () -> Unit ) { val colorScheme = when { dynamicColor && Build.VERSION.SDK_INT >= Build.VERSION_CODES.S -> { val context = LocalContext.current if (darkTheme) dynamicDarkColorScheme(context) else dynamicLightColorScheme(context) } darkTheme -> DarkColorScheme else -> LightColorScheme }
MaterialTheme( colorScheme = colorScheme, typography = FuturisticTypography, content = content ) }

package com.example.smarttasks.viewmodel

import android.app.Application
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import com.example.smarttasks.data.SmartTasksDatabase
import com.example.smarttasks.data.TareaRepository
import com.example.smarttasks.model.Tarea
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

class TaskViewModel(application: Application) : AndroidViewModel(application) {

    private val repository: TareaRepository

    // Estados de la UI
    private val _tareas = MutableStateFlow<List<Tarea>>(emptyList())
    val tareas: StateFlow<List<Tarea>> = _tareas.asStateFlow()

    private val _isLoading = MutableStateFlow(false)
    val isLoading: StateFlow<Boolean> = _isLoading.asStateFlow()

    private val _filtroActual = MutableStateFlow(FiltroTareas.TODAS)
    val filtroActual: StateFlow<FiltroTareas> = _filtroActual.asStateFlow()

    init {
        val tareaDao = SmartTasksDatabase.getDatabase(application).tareaDao()
        repository = TareaRepository(tareaDao)

        // Observar cambios en las tareas según el filtro
        viewModelScope.launch {
            _filtroActual.collect { filtro ->
                when (filtro) {
                    FiltroTareas.TODAS -> repository.getAllTareas()
                    FiltroTareas.PENDIENTES -> repository.getTareasPendientes()
                    FiltroTareas.COMPLETADAS -> repository.getTareasCompletadas()
                }.collect { listaTareas ->
                    _tareas.value = listaTareas
                }
            }
        }
    }

    fun agregarTarea(tarea: Tarea) {
        viewModelScope.launch {
            _isLoading.value = true
            repository.insertTarea(tarea)
            _isLoading.value = false
        }
    }

    fun marcarComoCompletada(tarea: Tarea) {
        viewModelScope.launch {
            repository.marcarComoCompletada(tarea)
        }
    }

    fun eliminarTarea(tarea: Tarea) {
        viewModelScope.launch {
            repository.deleteTarea(tarea)
        }
    }

    fun cambiarFiltro(filtro: FiltroTareas) {
        _filtroActual.value = filtro
    }

    fun limpiarCompletadas() {
        viewModelScope.launch {
            repository.deleteAllCompletadas()
        }
    }
}

enum class FiltroTareas {
    TODAS, PENDIENTES, COMPLETADAS
}

package com.example.smarttasks.viewmodel

import android.app.Application
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import com.example.smarttasks.data.SmartTasksDatabase
import com.example.smarttasks.data.TareaRepository
import com.example.smarttasks.model.Tarea
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import kotlinx.coroutines.flow.collectLatest

class TaskViewModel(application: Application) : AndroidViewModel(application) {

    private val repository: TareaRepository

    // Estados de la UI
    private val _tareas = MutableStateFlow<List<Tarea>>(emptyList())
    val tareas: StateFlow<List<Tarea>> = _tareas.asStateFlow()

    private val _isLoading = MutableStateFlow(false)
    val isLoading: StateFlow<Boolean> = _isLoading.asStateFlow()

    private val _filtroActual = MutableStateFlow(FiltroTareas.TODAS)
    val filtroActual: StateFlow<FiltroTareas> = _filtroActual.asStateFlow()

    init {
        val tareaDao = SmartTasksDatabase.getDatabase(application).tareaDao()
        repository = TareaRepository(tareaDao)

        // Observar cambios en las tareas según el filtro
        viewModelScope.launch {
            _filtroActual.collectLatest { filtro ->
                val flowToCollect = when (filtro) {
                    FiltroTareas.TODAS -> repository.getAllTareas()
                    FiltroTareas.PENDIENTES -> repository.getTareasPendientes()
                    FiltroTareas.COMPLETADAS -> repository.getTareasCompletadas()
                }

                flowToCollect.collect { listaTareas ->
                    _tareas.value = listaTareas
                }
            }
        }
    }

    fun agregarTarea(tarea: Tarea) {
        viewModelScope.launch {
            _isLoading.value = true
            repository.insertTarea(tarea)
            _isLoading.value = false
        }
    }

    fun marcarComoCompletada(tarea: Tarea) {
        viewModelScope.launch {
            repository.marcarComoCompletada(tarea)
        }
    }

    fun eliminarTarea(tarea: Tarea) {
        viewModelScope.launch {
            repository.deleteTarea(tarea)
        }
    }

    fun cambiarFiltro(filtro: FiltroTareas) {
        _filtroActual.value = filtro
    }

    fun limpiarCompletadas() {
        viewModelScope.launch {
            repository.deleteAllCompletadas()
        }
    }
}

enum class FiltroTareas {
    TODAS, PENDIENTES, COMPLETADAS
}

package com.example.smarttasks.viewmodel

import androidx.lifecycle.ViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

class ThemeViewModel : ViewModel() {

    private val _isDarkTheme = MutableStateFlow(false)
    val isDarkTheme: StateFlow<Boolean> = _isDarkTheme.asStateFlow()

    fun toggleTheme() {
        _isDarkTheme.value = !_isDarkTheme.value
    }

    fun setDarkTheme(isDark: Boolean) {
        _isDarkTheme.value = isDark
    }
}
